-- Mandatory final exception rolls back ALL changes, including audit events.
create temporary table regression_results(label text);
create function pg_temp.check_result(label text,passed boolean) returns void language plpgsql as $$
begin
  if passed is distinct from true then raise exception 'REGRESSION_FAILED: %',label; end if;
  insert into pg_temp.regression_results values(label);
end $$;
create function pg_temp.expect_error(label text,statement text,expected text) returns void language plpgsql as $$
declare code text;
begin
  begin execute statement; exception when others then code:=sqlerrm; end;
  perform pg_temp.check_result(label,code=expected or (expected='PERMISSION' and code like 'permission denied%'));
end $$;
grant all on pg_temp.regression_results to anon,authenticated,service_role;
-- Only inside this rollback-only test transaction: normalize unrelated demo
-- salaries so the publication tests isolate their own incomplete-salary cases.
update private.employee_compensation c set base_salary_idr=1000000 from public.employees e
  where e.id=c.employee_id and e.employment_status='ACTIVE' and c.base_salary_idr<=0;
do $tests$
declare hr uuid; manager uuid; emp uuid; disabled uuid; invited uuid; inactive uuid;
  emp_id uuid:='e0000000-0000-4000-8000-000000000002';
  hr_id uuid:='e0000000-0000-4000-8000-000000000001';
  account public.user_profiles; run public.payroll_runs; item public.payroll_items;
  leave_row public.leave_requests; review public.performance_reviews; employee public.employees;
  contact public.employee_contacts; salary bigint; v integer; claim jsonb;
  manager_leave public.leave_requests; correction public.attendance_corrections; policy public.hr_policy;
  kpi public.kpi_assessments; indicators jsonb; plan jsonb; applicant public.demo_applicants; report jsonb;
  correction_date date; today date:=(now() at time zone 'Asia/Jakarta')::date; notifications jsonb; initial_balance integer; other_actor uuid;
begin
  select user_id into strict hr from public.user_profiles where employee_id=hr_id;
  select user_id into strict emp from public.user_profiles where employee_id=emp_id;
  select user_id into strict manager from public.user_profiles where employee_id='e0000000-0000-4000-8000-000000000004';
  select user_id into strict disabled from public.user_profiles where account_status='DISABLED';
  select user_id into strict invited from public.user_profiles where account_status='INVITED';
  select user_id into strict inactive from public.user_profiles where employee_id='e0000000-0000-4000-8000-000000000008';
  select user_id into strict other_actor from public.user_profiles where employee_id='e0000000-0000-4000-8000-000000000005';
  perform set_config('request.jwt.claim.sub',hr::text,true); execute 'set local role authenticated';
  perform pg_temp.check_result('HR compensation RPC',public.employee_compensation_for_hr(emp_id)>0);
  select public.write_master('positions',null,'Regression unused master',null) into claim;
  perform pg_temp.check_result('Audited master create',claim->>'name'='Regression unused master');
  select public.write_master('positions',(claim->>'id')::uuid,'Regression renamed master',(claim->>'version')::integer) into claim;
  perform pg_temp.check_result('Versioned master rename',(claim->>'version')::integer=2);
  perform pg_temp.expect_error('Master direct mutation denied','update public.positions set name=name','PERMISSION');
  perform pg_temp.expect_error('Direct employee writes denied',format('update public.employees set full_name=full_name where id=%L',emp_id),'PERMISSION');
  perform pg_temp.expect_error('TRUNCATE denied','truncate public.employees cascade','PERMISSION');
  select version into v from public.employees where id=hr_id;
  perform pg_temp.expect_error('HR cannot deactivate own employee',format('select public.update_employee(%L,%s,p_employment_status=>''INACTIVE'')',hr_id,v),'FORBIDDEN');
  perform pg_temp.expect_error('Null employee version rejected',format('select public.update_employee(%L,null)',emp_id),'VALIDATION_ERROR');
  select * into account from public.user_profiles where user_id=hr;
  perform pg_temp.expect_error('HR cannot demote own account',format('select public.update_account(%L,''EMPLOYEE'',null,%s)',hr,account.version),'FORBIDDEN');
  perform pg_temp.expect_error('Null account version rejected',format('select public.update_account(%L,null,null,null)',hr),'VALIDATION_ERROR');
  select version into v from public.employees where id=emp_id;
  perform pg_temp.expect_error('Linked Auth email protected',format('select public.update_employee(%L,%s,p_work_email=>''mismatch@example.test'')',emp_id,v),'VALIDATION_ERROR');
  select * into employee from public.create_employee('CI-ROLLBACK','Database regression','ci-rollback@example.test',
    'd0000000-0000-4000-8000-000000000002','b0000000-0000-4000-8000-000000000002','ACTIVE','2026-01-01','081234567890','Rollback',1234567);
  perform pg_temp.check_result('Atomic employee/contact/compensation',employee.id is not null and
    exists(select 1 from public.employee_contacts where employee_id=employee.id) and public.employee_compensation_for_hr(employee.id)=1234567);
  select * into run from public.create_payroll_run('2099-12');
  select * into item from public.payroll_items where payroll_run_id=run.id and employee_id=emp_id;
  select * into item from public.update_payroll_item(item.id,100,200,50,item.version);
  perform pg_temp.check_result('Component edit bumps run version',(select version from public.payroll_runs where id=run.id)=run.version+1);
  select * into run from public.payroll_runs where id=run.id;
  perform pg_temp.check_result('Payroll computation',item.net_salary_idr=item.base_salary_idr+250);
  salary:=item.base_salary_idr;
  select version into v from public.employees where id=emp_id;
  perform public.update_employee(emp_id,v,p_base_salary_idr=>salary+100);
  perform pg_temp.check_result('Salary change detected',(public.payroll_run_readiness(run.id)->>'staleItemCount')::int=1);
  perform pg_temp.expect_error('Stale draft cannot publish',format('select public.publish_payroll_run(%L,%s)',run.id,run.version),'PAYROLL_NOT_READY');
  select version into v from public.employees where id=employee.id;
  perform public.update_employee(employee.id,v,p_base_salary_idr=>0);
  perform pg_temp.check_result('Zero salary is not configured',(public.payroll_run_readiness(run.id)->>'missingSalaryCount')::int=1);
  perform pg_temp.expect_error('Zero salary cannot publish',format('select public.publish_payroll_run(%L,%s)',run.id,run.version),'PAYROLL_NOT_READY');
  select version into v from public.employees where id=employee.id;
  perform public.update_employee(employee.id,v,p_base_salary_idr=>1234567);
  select * into employee from public.create_employee('CI-ROLLBACK-NEW','New payroll regression','ci-payroll-new@example.test',
    'd0000000-0000-4000-8000-000000000002','b0000000-0000-4000-8000-000000000002','ACTIVE','2026-01-01','081234567890','Rollback',2345678);
  perform pg_temp.check_result('New employee detected',(public.payroll_run_readiness(run.id)->>'missingItemCount')::int=1);
  perform pg_temp.expect_error('Missing employee prevents publication',format('select public.publish_payroll_run(%L,%s)',run.id,run.version),'PAYROLL_NOT_READY');
  v:=run.version;
  select * into run from public.sync_payroll_run(run.id,run.version);
  perform pg_temp.check_result('Sync adds new employee',(select base_salary_idr=2345678 from public.payroll_items where payroll_run_id=run.id and employee_id=employee.id));
  perform pg_temp.check_result('Sync preserves components',(select allowance_idr=100 and bonus_idr=200 and deduction_idr=50 from public.payroll_items where id=item.id));
  perform pg_temp.expect_error('Sync version checked',format('select public.sync_payroll_run(%L,%s)',run.id,v),'VERSION_CONFLICT');
  perform pg_temp.check_result('Synced run ready',(public.payroll_run_readiness(run.id)->>'ready')::boolean);
  select version into v from public.employees where id=employee.id;
  perform public.update_employee(employee.id,v,p_employment_status=>'INACTIVE');
  perform pg_temp.check_result('Inactive draft item detected',(public.payroll_run_readiness(run.id)->>'inactiveItemCount')::int=1);
  select * into run from public.sync_payroll_run(run.id,run.version);
  perform pg_temp.check_result('Sync removes only inactive draft item',not exists(select 1 from public.payroll_items where payroll_run_id=run.id and employee_id=employee.id));
  perform public.publish_payroll_run(run.id,run.version);
  select * into item from public.payroll_items where payroll_run_id=run.id and employee_id=emp_id;
  perform pg_temp.check_result('Publish refreshes compensation',item.base_salary_idr=salary+100 and item.net_salary_idr=salary+350);
  perform pg_temp.expect_error('Published payroll immutable',format('select public.update_payroll_item(%L,0,0,0,%s)',item.id,item.version),'PAYROLL_ALREADY_PUBLISHED');
  perform pg_temp.expect_error('Published run cannot sync',format('select public.sync_payroll_run(%L,%s)',run.id,run.version),'PAYROLL_ALREADY_PUBLISHED');
  perform pg_temp.expect_error('Null publish version rejected',format('select public.publish_payroll_run(%L,null)',run.id),'VALIDATION_ERROR');
  select * into run from public.create_payroll_run('2099-11');
  select * into item from public.payroll_items where payroll_run_id=run.id and employee_id=emp_id;
  perform public.update_payroll_item(item.id,0,0,item.base_salary_idr,item.version);
  select * into run from public.payroll_runs where id=run.id;
  select version into v from public.employees where id=emp_id;
  perform public.update_employee(emp_id,v,p_base_salary_idr=>100);
  perform pg_temp.expect_error('Publish checks refreshed deduction',format('select public.publish_payroll_run(%L,%s)',run.id,run.version),'PAYROLL_NOT_READY');
  perform pg_temp.expect_error('Sync excessive deduction rolls back',format('select public.sync_payroll_run(%L,%s)',run.id,run.version),'VALIDATION_ERROR');
  -- Invitation tests require an active, unlinked employee, not the inactive payroll test target.
  select * into employee from public.employees where employee_no='CI-ROLLBACK';
  select public.claim_account_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',employee.id,'EMPLOYEE',repeat('a',64)) into claim;
  perform pg_temp.check_result('Private invitation claim',claim->>'state'='PROCESSING' and claim->>'operationId' is not null);
  perform pg_temp.expect_error('Same key does not resend',format('select public.claim_account_invitation(''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',%L,''EMPLOYEE'',repeat(''a'',64))',employee.id),'OPERATION_IN_PROGRESS');
  perform pg_temp.expect_error('Invitation payload conflict',format('select public.claim_account_invitation(''aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'',%L,''MANAGER'',repeat(''b'',64))',employee.id),'IDEMPOTENCY_CONFLICT');
  perform pg_temp.expect_error('Public cannot finalize invitation',format('select public.finish_account_invitation(%L,%L)',claim->>'operationId',emp),'PERMISSION');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform pg_temp.expect_error('Employee salary access denied',format('select public.employee_compensation_for_hr(%L)',emp_id),'FORBIDDEN');
  perform pg_temp.expect_error('Direct contact writes denied',format('update public.employee_contacts set phone=phone where employee_id=%L',emp_id),'PERMISSION');
  select * into contact from public.employee_contacts where employee_id=emp_id;
  select version into v from public.employees where id=emp_id;
  perform public.update_own_contact(contact.version,'081234567890','Regression rollback');
  perform pg_temp.check_result('Contact bumps aggregate',(select version from public.employees where id=emp_id)=v+1);
  perform pg_temp.expect_error('Null contact version rejected','select public.update_own_contact(null,''081234567890'',''Rollback'')','VALIDATION_ERROR');
  select * into leave_row from public.create_leave_request('PERMISSION','2099-01-05','2099-01-05','Regression rollback');
  perform pg_temp.check_result('Leave creates pending working day',leave_row.status='PENDING' and leave_row.working_days=1);
  perform pg_temp.expect_error('Overlap rejected','select public.create_leave_request(''SICK'',''2099-01-05'',''2099-01-05'',''Overlap'')','LEAVE_OVERLAP');
  perform pg_temp.expect_error('Quota enforced','select public.create_leave_request(''ANNUAL'',''2099-02-02'',''2099-02-27'',''Quota'')','LEAVE_BALANCE_EXCEEDED');
  perform set_config('request.jwt.claim.sub',manager::text,true);
  perform pg_temp.check_result('Manager payroll only own published',(select count(*) from public.payroll_items)>0 and
    not exists(select 1 from public.payroll_items where employee_id<>private.current_employee_id() or status<>'PUBLISHED'));
  perform pg_temp.expect_error('Manager cannot read readiness',format('select public.payroll_run_readiness(%L)',run.id),'FORBIDDEN');
  perform pg_temp.expect_error('Manager cannot sync payroll',format('select public.sync_payroll_run(%L,%s)',run.id,run.version),'FORBIDDEN');
  select * into manager_leave from public.create_leave_request('PERMISSION','2099-01-05','2099-01-05','Manager personal leave');
  perform pg_temp.check_result('Manager can request personal leave',manager_leave.employee_id=private.current_employee_id());
  perform pg_temp.expect_error('Manager cannot approve self',format('select public.decide_leave_request(%L,''APPROVED'',null,%s)',manager_leave.id,manager_leave.version),'FORBIDDEN');
  perform pg_temp.expect_error('Manager cannot decide team leave',format('select public.decide_leave_request(%L,''REJECTED'',''Rollback'',%s)',leave_row.id,leave_row.version),'FORBIDDEN');
  perform pg_temp.expect_error('Manager manual scoring retired',format('select public.upsert_performance_review(%L,''2099-12'',80,''Rollback'',null)',emp_id),'FORBIDDEN');
  perform pg_temp.expect_error('Manager cannot change HR policy','select public.update_hr_policy(1,''08:00'',''17:00'',array[1,2,3,4,5],12,array[]::date[],7)','FORBIDDEN');
  perform pg_temp.expect_error('Manager audit denied','select public.hr_audit_log()','FORBIDDEN');
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform public.decide_leave_request(leave_row.id,'REJECTED','Regression rollback',leave_row.version);
  perform pg_temp.check_result('HR handles ordinary employee leave',(select status='REJECTED' and decided_by=hr and decided_at is not null from public.leave_requests where id=leave_row.id));
  perform public.decide_leave_request(manager_leave.id,'APPROVED',null,manager_leave.version);
  perform pg_temp.check_result('HR decides manager personal leave',(select status='APPROVED' and decided_by=hr from public.leave_requests where id=manager_leave.id));
  select * into manager_leave from public.create_leave_request('PERMISSION','2099-01-05','2099-01-05','HR personal leave');
  perform pg_temp.expect_error('HR cannot approve self',format('select public.decide_leave_request(%L,''APPROVED'',null,%s)',manager_leave.id,manager_leave.version),'FORBIDDEN');
  select * into policy from public.hr_policy where id=1;
  select * into policy from public.update_hr_policy(policy.policy_version,'08:00','17:00',array[1,2,3,4,5],12,array[today],7);
  perform pg_temp.check_result('HR policy versioned and saved',policy.holiday_dates=array[today]);
  perform pg_temp.expect_error('Policy stale version rejected',format('select public.update_hr_policy(%s,''08:00'',''17:00'',array[1],12,array[]::date[],7)',policy.policy_version-1),'VERSION_CONFLICT');
  perform pg_temp.expect_error('Invalid working day rejected',format('select public.update_hr_policy(%s,''08:00'',''17:00'',array[8],12,array[]::date[],7)',policy.policy_version),'VALIDATION_ERROR');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform pg_temp.expect_error('Checkin rejects holiday','select public.attendance_check_in()','NON_WORKING_DAY');
  perform pg_temp.expect_error('Employee audit denied','select public.hr_audit_log()','FORBIDDEN');
  select available_days into initial_balance from public.leave_balance(emp_id,2099);
  select * into manager_leave from public.create_leave_request('ANNUAL','2099-01-19','2099-01-19','Cancel pending regression');
  perform pg_temp.check_result('Pending annual leave reserves quota',(select available_days from public.leave_balance(emp_id,2099))=initial_balance-manager_leave.working_days);
  perform set_config('request.jwt.claim.sub',manager::text,true);
  perform pg_temp.expect_error('Manager cannot cancel colleague leave',format('select public.cancel_leave_request(%L,%s)',manager_leave.id,manager_leave.version),'NOT_FOUND');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform public.cancel_leave_request(manager_leave.id,manager_leave.version);
  perform pg_temp.check_result('Cancel preserves history and releases quota',(select status='CANCELLED' and cancelled_at is not null from public.leave_requests where id=manager_leave.id) and
    (select available_days from public.leave_balance(emp_id,2099))=initial_balance);
  select * into manager_leave from public.create_leave_request('PERMISSION','2099-01-19','2099-01-19','Cancelled dates can be reused');
  perform pg_temp.check_result('Cancelled does not overlap',manager_leave.status='PENDING');
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform public.decide_leave_request(manager_leave.id,'APPROVED',null,manager_leave.version);
  perform pg_temp.check_result('HR handles department with an active Manager',(select status='APPROVED' and decided_by=hr from public.leave_requests where id=manager_leave.id));
  perform set_config('request.jwt.claim.sub',other_actor::text,true);
  select * into manager_leave from public.create_leave_request('PERMISSION','2099-01-05','2099-01-05','Department without manager');
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform public.decide_leave_request(manager_leave.id,'APPROVED',null,manager_leave.version);
  perform pg_temp.check_result('HR fallback resolves department without manager',(select status='APPROVED' and decided_by=hr from public.leave_requests where id=manager_leave.id));
  perform set_config('request.jwt.claim.sub',other_actor::text,true);
  select version into v from public.leave_requests where id=manager_leave.id;
  perform pg_temp.expect_error('Approved leave cannot be directly cancelled',format('select public.cancel_leave_request(%L,%s)',manager_leave.id,v),'LEAVE_ALREADY_DECIDED');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  notifications:=public.my_notifications();
  perform pg_temp.check_result('Notifications scoped to own published payroll',exists(select 1 from jsonb_array_elements(notifications) n where n->>'id' like 'payroll:%'));
  perform public.read_my_notifications(array[(notifications->0)->>'id']);
  perform pg_temp.check_result('Notification read receipt saved',exists(select 1 from jsonb_array_elements(public.my_notifications()) n where n->>'id'=((notifications->0)->>'id') and (n->>'read')::boolean));
  -- Corrections use real dates but all mutations are rolled back with this transaction.
  select max(d::date) into correction_date from generate_series(today-30,today-1,interval '1 day') d
    where extract(isodow from d) between 1 and 5 and not exists(select 1 from public.leave_requests l where l.employee_id=emp_id and l.status='APPROVED' and d::date between l.start_date and l.end_date);
  select * into correction from public.request_attendance_correction(correction_date,'08:00:30','17:00','Regression forgotten attendance');
  perform pg_temp.check_result('Correction pending does not change attendance',correction.status='PENDING');
  perform pg_temp.expect_error('Duplicate pending correction denied',format('select public.request_attendance_correction(%L,''08:00'',''17:00'',''Duplicate'')',correction_date),'DUPLICATE_CORRECTION');
  perform pg_temp.expect_error('Employee cannot approve correction',format('select public.decide_attendance_correction(%L,''APPROVED'',''Review'',%s)',correction.id,correction.version),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform public.decide_attendance_correction(correction.id,'APPROVED','Checked regression',correction.version);
  perform pg_temp.check_result('HR approved correction retains seconds and status',(select status='LATE' and check_in_at=(correction_date+time '08:00:30') at time zone 'Asia/Jakarta' from public.attendances where employee_id=emp_id and work_date=correction_date));
  perform pg_temp.expect_error('Correction stale decision rejected',format('select public.decide_attendance_correction(%L,''REJECTED'',''Stale'',%s)',correction.id,correction.version),'VERSION_CONFLICT');
  perform pg_temp.check_result('HR audit is read-only and populated',jsonb_array_length(public.hr_audit_log())>0);
  select * into correction from public.request_attendance_correction(correction_date,'08:00','17:00','HR own correction');
  perform pg_temp.expect_error('HR cannot approve own correction',format('select public.decide_attendance_correction(%L,''APPROVED'',''Review'',%s)',correction.id,correction.version),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  select * into correction from public.request_attendance_correction(correction_date,'08:00','17:00','Concurrent attendance regression');
  execute 'reset role';
  update public.attendances set updated_at=now() where employee_id=emp_id and work_date=correction_date;
  execute 'set local role authenticated';
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform pg_temp.expect_error('Changed attendance cannot be overwritten by stale correction',format('select public.decide_attendance_correction(%L,''APPROVED'',''Review'',%s)',correction.id,correction.version),'VERSION_CONFLICT');
  indicators:='[{"name":"Tasks","unit":"%","direction":"HIGHER","target":100,"weight":70,"actual":80,"measurement":"Tasks completed / planned * 100","evidence":"8/10 test tasks"},{"name":"Errors","unit":"cases","direction":"LOWER","target":2,"weight":30,"actual":4,"measurement":"Count of reviewed defects","evidence":"4 test defects"}]'::jsonb;
  plan:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(indicators,'{0,actual}','null'),'{1,actual}','null'),'{0,evidence}','""'),'{1,evidence}','""');
  perform pg_temp.expect_error('HR cannot invent targets',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,indicators),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',manager::text,true);
  perform pg_temp.expect_error('Manager cannot score own KPI',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',private.current_employee_id(),indicators),'FORBIDDEN');
  perform pg_temp.expect_error('Manager cannot score cross department KPI',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',hr_id,indicators),'NOT_FOUND');
  perform pg_temp.expect_error('KPI invalid weights rejected',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,jsonb_set(indicators,'{0,weight}','69')),'VALIDATION_ERROR');
  perform pg_temp.expect_error('KPI zero target rejected',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,jsonb_set(indicators,'{0,target}','0')),'VALIDATION_ERROR');
  perform pg_temp.expect_error('KPI negative actual rejected',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,jsonb_set(indicators,'{0,actual}','-1')),'VALIDATION_ERROR');
  perform pg_temp.expect_error('KPI arbitrary score field rejected',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,jsonb_set(indicators,'{0,score}','100')),'VALIDATION_ERROR');
  perform pg_temp.expect_error('Manager cannot submit realisations',format('select public.save_kpi(%L,''2099-11'',%L,'''',null)',emp_id,indicators),'FORBIDDEN');
  select * into kpi from public.save_kpi(emp_id,'2099-11',plan,'',null);
  perform pg_temp.check_result('KPI draft unscored',kpi.status='DRAFT' and kpi.score is null);
  perform pg_temp.expect_error('Manager cannot finalize KPI',format('select public.publish_kpi(%L,%s,null)',kpi.id,kpi.version),'FORBIDDEN');
  perform pg_temp.expect_error('Goals stale sharing rejected',format('select public.share_kpi_goals(%L,999)',kpi.id),'VERSION_CONFLICT');
  select * into kpi from public.share_kpi_goals(kpi.id,kpi.version);
  perform pg_temp.expect_error('Manager cannot edit shared targets',format('select public.save_kpi(%L,''2099-11'',%L,'''',%s)',emp_id,plan,kpi.version),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform pg_temp.check_result('Employee cannot see draft KPI',(select count(*) from public.kpi_assessments where id=kpi.id)=0);
  perform pg_temp.check_result('Employee sees safe shared targets',exists(select 1 from public.kpi_goal_plans g where g.assessment_id=kpi.id and not exists(select 1 from jsonb_array_elements(g.indicators) i where i ? 'actual' or i ? 'evidence')));
  perform pg_temp.check_result('Owner notified of safe targets',exists(select 1 from jsonb_array_elements(public.my_notifications()) n where n->>'id'='kpi-goals:'||kpi.id and n->>'view'='kpi'));
  perform pg_temp.expect_error('Employee cannot share goals',format('select public.share_kpi_goals(%L,%s)',kpi.id,kpi.version),'FORBIDDEN');
  perform pg_temp.expect_error('Goals direct mutation denied','update public.kpi_goal_plans set indicators=indicators','PERMISSION');
  perform pg_temp.expect_error('Employee cannot save KPI',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',null)',emp_id,indicators),'FORBIDDEN');
  perform pg_temp.expect_error('KPI direct mutation denied','update public.kpi_assessments set notes=notes','PERMISSION');
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform pg_temp.check_result('HR can monitor draft KPI',(select count(*) from public.kpi_assessments where id=kpi.id)=1);
  perform pg_temp.expect_error('HR cannot mutate ordinary employee goals',format('select public.share_kpi_goals(%L,%s)',kpi.id,kpi.version),'FORBIDDEN');
  perform pg_temp.expect_error('HR cannot alter Manager targets',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',%s)',emp_id,jsonb_set(indicators,'{0,target}','101'),kpi.version),'VALIDATION_ERROR');
  perform pg_temp.expect_error('HR needs complete actuals and evidence',format('select public.publish_kpi(%L,%s,null)',kpi.id,kpi.version),'VALIDATION_ERROR');
  perform pg_temp.expect_error('KPI stale save rejected',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',999)',emp_id,indicators),'VERSION_CONFLICT');
  select * into kpi from public.save_kpi(emp_id,'2099-11',indicators,'Rollback',kpi.version);
  execute 'reset role';
  insert into public.performance_reviews(employee_id,period,score,notes,assessed_by) values(emp_id,'2099-11',90,'Preserved legacy fixture',hr) returning * into review;
  execute 'set local role authenticated';
  perform pg_temp.expect_error('KPI cannot silently replace existing review',format('select public.publish_kpi(%L,%s,null)',kpi.id,kpi.version),'VERSION_CONFLICT');
  select * into kpi from public.publish_kpi(kpi.id,kpi.version,review.version);
  perform pg_temp.check_result('KPI weighted score computed by database',kpi.score=71 and kpi.status='PUBLISHED');
  perform pg_temp.check_result('KPI replaces review atomically with provenance',(select score=71 and kpi_id=kpi.id from public.performance_reviews where id=review.id));
  perform pg_temp.expect_error('KPI final immutable',format('select public.save_kpi(%L,''2099-11'',%L,''Rollback'',%s)',emp_id,indicators,kpi.version),'KPI_FINALIZED');
  perform pg_temp.expect_error('Manual review endpoint retired',format('select public.upsert_performance_review(%L,''2099-11'',100,''Override'',%s)',emp_id,review.version+1),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform pg_temp.check_result('Employee sees only own final KPI',(select count(*) from public.kpi_assessments where id=kpi.id)=1 and not exists(select 1 from public.kpi_assessments where employee_id<>emp_id or status<>'PUBLISHED'));
  perform set_config('request.jwt.claim.sub',other_actor::text,true);
  perform pg_temp.check_result('Other employee cannot see KPI',(select count(*) from public.kpi_assessments where id=kpi.id)=0);
  perform pg_temp.check_result('Other employee cannot see shared goals',(select count(*) from public.kpi_goal_plans where assessment_id=kpi.id)=0);
  perform set_config('request.jwt.claim.sub',manager::text,true);
  select * into kpi from public.save_kpi(emp_id,'2099-10',plan,'',null);
  select * into kpi from public.share_kpi_goals(kpi.id,kpi.version);
  perform set_config('request.jwt.claim.sub',hr::text,true);
  select * into kpi from public.save_kpi(emp_id,'2099-10',jsonb_set(jsonb_set(indicators,'{0,actual}','200'),'{1,actual}','0'),'Capped achievement',kpi.version);
  select * into kpi from public.publish_kpi(kpi.id,kpi.version,null);
  perform pg_temp.check_result('KPI overachievement capped and lower zero handled',kpi.score=100);
  perform set_config('request.jwt.claim.sub',hr::text,true);
  perform pg_temp.check_result('HR evaluates ordinary staff and never self',exists(select 1 from public.kpi_assessment_targets() where id=emp_id) and not exists(select 1 from public.kpi_assessment_targets() where id=hr_id));
  report:=public.monthly_performance_report('2099-11');
  perform pg_temp.check_result('Monthly report includes final provenance',exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=emp_id::text and (r->>'score')::integer=71 and r->>'scoreSource'='KPI'));
  perform pg_temp.check_result('Future days never become absences',not exists(select 1 from jsonb_array_elements(report) r where (r->>'workDays')::integer<>0 or (r->>'absenceDays')::integer<>0));
  perform pg_temp.check_result('Monthly report has readable identity',exists(select 1 from jsonb_array_elements(report) r where length(r->>'employeeNo')>0 and length(r->>'name')>0));
  perform pg_temp.expect_error('Invalid report period denied','select public.monthly_performance_report(''2026-13'')','VALIDATION_ERROR');
  select * into employee from public.create_employee('CI-RECAP','Monthly regression','ci-recap@example.test',
    'd0000000-0000-4000-8000-000000000002','b0000000-0000-4000-8000-000000000002','ACTIVE','2026-02-01','081234567890','Rollback',1000000);
  execute 'reset role';
  insert into public.attendances(employee_id,work_date,check_in_at,check_out_at,status,policy_version) values
    (employee.id,'2026-02-02','2026-02-02 01:01:00+00','2026-02-02 10:00:00+00','LATE',1),
    (employee.id,'2026-02-03','2026-02-03 00:55:00+00',null,'PRESENT',1),
    (employee.id,'2026-02-07','2026-02-07 00:55:00+00',null,'PRESENT',1);
  insert into public.leave_requests(employee_id,type,start_date,end_date,working_days,reason,status,decided_by,decided_at,policy_version) values
    (employee.id,'ANNUAL','2026-02-04','2026-02-04',1,'Rollback','APPROVED',hr,now(),1),
    (employee.id,'PERMISSION','2026-02-05','2026-02-05',1,'Rollback','APPROVED',hr,now(),1),
    (employee.id,'SICK','2026-02-06','2026-02-06',1,'Rollback','APPROVED',hr,now(),1);
  execute 'set local role authenticated';
  report:=public.monthly_performance_report('2026-02');
  perform pg_temp.check_result('Monthly recap counts working days and ignores weekend attendance',exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=employee.id::text and (r->>'workDays')::integer=20 and (r->>'presentDays')::integer=2 and (r->>'lateDays')::integer=1));
  perform pg_temp.check_result('Monthly recap excludes approved leave from absence',exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=employee.id::text and (r->>'annualLeaveDays')::integer=1 and (r->>'permissionDays')::integer=1 and (r->>'sickDays')::integer=1 and (r->>'absenceDays')::integer=15 and (r->>'incompleteDays')::integer=1));
  perform pg_temp.check_result('Unassessed monthly score is JSON null, never zero',exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=employee.id::text and r->'score'='null'::jsonb));
  select * into applicant from public.demo_applicants order by id limit 1;
  perform pg_temp.check_result('Seeded applicants are dummy',(select count(*)=20 and bool_and(is_dummy) from public.demo_applicants));
  select * into applicant from public.update_demo_applicant(applicant.id,90,80,70,'Rollback only',applicant.version);
  perform pg_temp.check_result('HR updates applicant version',applicant.version=2 and applicant.technical_score=80);
  perform pg_temp.expect_error('Applicant stale update denied',format('select public.update_demo_applicant(%L,90,80,70,'''',1)',applicant.id),'VERSION_CONFLICT');
  perform pg_temp.expect_error('Applicant invalid score denied',format('select public.update_demo_applicant(%L,-1,80,70,'''',2)',applicant.id),'VALIDATION_ERROR');
  perform pg_temp.expect_error('Applicant direct mutation denied','update public.demo_applicants set notes=notes','PERMISSION');
  perform set_config('request.jwt.claim.sub',manager::text,true);
  report:=public.monthly_performance_report('2099-11');
  perform pg_temp.check_result('Manager report excludes cross department',not exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=hr_id::text));
  perform pg_temp.check_result('Manager can monitor published KPI',exists(select 1 from jsonb_array_elements(report) r where r->>'employeeId'=emp_id::text and (r->>'score')::integer=71));
  perform pg_temp.expect_error('Manager cannot edit applicant',format('select public.update_demo_applicant(%L,90,80,70,'''',2)',applicant.id),'FORBIDDEN');
  perform set_config('request.jwt.claim.sub',emp::text,true);
  perform pg_temp.check_result('Employee cannot read applicants',(select count(*) from public.demo_applicants)=0);
  perform pg_temp.expect_error('Employee cannot read monthly report','select public.monthly_performance_report(''2099-11'')','FORBIDDEN');
  execute 'set local role anon';
  perform pg_temp.expect_error('Anonymous KPI RPC denied',format('select public.publish_kpi(%L,%s,null)',kpi.id,kpi.version),'PERMISSION');
  perform pg_temp.expect_error('Anonymous notifications RPC denied','select public.my_notifications()','PERMISSION');
  execute 'set local role authenticated';
  foreach emp in array array[disabled,invited,inactive] loop
    perform set_config('request.jwt.claim.sub',emp::text,true);
    perform pg_temp.check_result('Inactive actor directory hidden: '||emp::text,(select count(*) from public.employees)=0);
    perform pg_temp.check_result('Inactive actor KPI hidden: '||emp::text,(select count(*) from public.kpi_assessments)=0);
    perform pg_temp.check_result('Inactive actor KPI goals hidden: '||emp::text,(select count(*) from public.kpi_goal_plans)=0);
    perform pg_temp.expect_error('Inactive balance denied: '||emp::text,format('select public.leave_balance((select employee_id from public.user_profiles where user_id=%L),2026)',emp),'FORBIDDEN');
  end loop;
  execute 'reset role';
  raise exception 'HRIS_REGRESSION_PASS:%', (select count(*) from pg_temp.regression_results);
end $tests$;
